// Cloudflare Worker entry point: the OpenNext-generated Next.js handler, plus
// a scheduled handler for the daily storm check (see `triggers` in
// wrangler.jsonc).

// `.open-next/worker.js` is generated by `opennextjs-cloudflare build`. This
// file is compiled by Wrangler, not Next.js, so it is excluded in tsconfig.json.
import { default as handler } from "./.open-next/worker.js";

type Env = { SITE_URL?: string; CRON_SECRET?: string };
type Ctx = { waitUntil(promise: Promise<unknown>): void };

const worker = {
  fetch: handler.fetch,

  async scheduled(_controller: unknown, env: Env, ctx: Ctx) {
    const url = `${env.SITE_URL ?? "http://localhost"}/api/cron/storm-check`;
    const request = new Request(url, {
      headers: { authorization: `Bearer ${env.CRON_SECRET}` },
    });
    ctx.waitUntil(
      handler.fetch(request, env, ctx).then(async (res: Response) => {
        console.log(`Storm check: HTTP ${res.status} ${await res.text()}`);
      }),
    );
  },
};

export default worker;
